package com.zomiggy.security;
import com.zomiggy.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private static final int MIN_SECRET_BYTES = 32; private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiration){String configuredSecret=secret == null ? "" : secret.trim();if(configuredSecret.getBytes(StandardCharsets.UTF_8).length < MIN_SECRET_BYTES)throw new IllegalStateException("JWT_SECRET must be at least 32 bytes long");key=Keys.hmacShaKeyFor(configuredSecret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String generate(User user){return Jwts.builder().subject(user.getMobile()).claim("role",user.getRole().name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }